import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
assert.equal(process.platform, "linux");
const root = fileURLToPath(new URL("../", import.meta.url));
const checkpointPath = path.join(root, ".work/rrsi-manifest-state-source-checkpoint-v2.json");
const checkpoint = JSON.parse(fs.readFileSync(checkpointPath, "utf8"));
const isolated = path.join(root, checkpoint.worktree), sha = (bytes) => createHash("sha256").update(bytes).digest("hex");
const check = () => { for (const entry of checkpoint.sourceDigests)
  assert.equal(sha(fs.readFileSync(path.join(isolated, entry.path))), entry.sha256, entry.path); };
check();
const helper = path.join(isolated, "packages/cli/__tests__/fixtures/rrsi-manifest-state-process.mjs");
const temp = fs.realpathSync.native(os.tmpdir()), results = [];
const wsl1 = /^4\.4\..*-microsoft$/i.test(os.release());
for (const kind of ["catalog", "head"]) for (const mode of ["fifo", "directory", "directory-mode", "symlink"]) {
  const directory = fs.mkdtempSync(path.join(temp, "cc-manifest-state-process-")), start = Date.now();
  try {
    const response = spawnSync(process.execPath, [helper, path.join(directory, kind), kind, mode], {
      encoding: "utf8", timeout: 15_000, windowsHide: true,
    });
    assert.equal(response.error, undefined, "child must finish before watchdog");
    assert.equal(response.status, 2, response.stderr);
    const value = JSON.parse(response.stderr);
    assert.equal(value.inspectionError, undefined);
    assert.equal(value.code, "CC_EVOLUTION_MANIFEST_STATE_READ_FAILED");
    const nativeDenial = mode === "directory" && wsl1;
    const directoryCheck = mode === "directory-mode" || (mode === "directory" && !nativeDenial);
    assert.equal(value.message, nativeDenial ? `manifest ${kind} bounded state read failed`
      : directoryCheck ? `manifest ${kind} directory physical identity changed`
      : `manifest ${kind} file identity is invalid`);
    assert.equal(value.causeCode, nativeDenial ? "EACCES" : undefined);
    assert.equal(value.faultInjected, true);
    assert.equal(value.opens, mode === "symlink" ? 0 : 1); assert.equal(value.rawReads, 0);
    assert.equal(value.actualReadBytes, mode.startsWith("directory") ? value.expectedSize : 0);
    assert.equal(value.liveDescriptors, 0); assert.equal(value.savedByteLength, value.expectedSize);
    assert.equal(value.preservedLeafInode, value.originalLeafInode);
    const current = path.join(directory, kind, `manifest-${kind}.json`);
    const preserved = mode === "directory" && !nativeDenial
      ? path.join(directory, "saved-directory", `manifest-${kind}.json`)
      : mode.startsWith("directory") ? current : path.join(directory, "saved-state");
    const saved = fs.readFileSync(preserved);
    assert.equal(saved.length, value.expectedSize);
    const original = JSON.parse(saved);
    const entry = kind === "head" ? original.head : original.manifests[0];
    assert.equal(entry.payload, "x".repeat(100_000));
    assert.equal(entry.headDigest, "test-head"); assert.equal(entry.manifestDigest, "test-manifest");
    const expectedEntry = { headDigest: "test-head", manifestDigest: "test-manifest", payload: "x".repeat(100_000) };
    const expectedState = kind === "head"
      ? { head: expectedEntry, schema: "chainlesschain.evolution-ledger-file-manifest-head-state/v2" }
      : { manifests: [expectedEntry], schema: "chainlesschain.evolution-ledger-file-manifest-catalog-state/v2" };
    assert.deepEqual(saved, Buffer.from(JSON.stringify(expectedState) + "\n"), "entire original state bytes must survive the fault");
    if (mode === "fifo") {
      assert.equal(value.actualFifoVerified, true); assert.equal(fs.lstatSync(current).isFIFO(), true);
    } else if (mode === "directory") {
      assert.equal(value.directoryMoved, !nativeDenial); assert.equal(value.directoryCopied, !nativeDenial);
      assert.equal(value.directoryModeChanged, false);
      if (nativeDenial) {
        assert.equal(value.currentDirectoryInode, value.originalDirectoryInode);
        assert.equal(value.currentDirectoryMode, value.originalDirectoryMode);
        assert.equal(fs.existsSync(path.join(directory, "saved-directory")), false);
      } else {
        assert.notEqual(value.currentDirectoryInode, value.originalDirectoryInode);
        assert.equal(saved.equals(fs.readFileSync(current)), true);
      }
    } else if (mode === "directory-mode") {
      assert.equal(value.directoryMoved, false); assert.equal(value.directoryCopied, false);
      // Two samples reach the injection; error reporting lstat of the preserved
      // leaf contributes the third sample after the reader has already failed.
      assert.equal(value.directoryModeChanged, true); assert.equal(value.leafPathSamples, 3);
      assert.equal(value.originalDirectoryMode & 0o777, 0o700);
      assert.equal(value.currentDirectoryMode & 0o777, 0o710);
      assert.equal(value.currentDirectoryInode, value.originalDirectoryInode);
      assert.equal(value.currentDirectoryMode, value.originalDirectoryMode ^ 0o010);
      fs.chmodSync(path.dirname(current), value.originalDirectoryMode & 0o777);
      assert.equal(fs.lstatSync(path.dirname(current)).mode, value.originalDirectoryMode);
    } else {
      assert.equal(value.actualDanglingSymlinkVerified, true); assert.equal(fs.lstatSync(current).isSymbolicLink(), true);
    }
    results.push({ kind, mode, status: "passed", durationMs: Date.now() - start, childWatchdogMs: 15000,
      childTimedOut: false, ...value, savedBytesVerified: true,
      nativeRenameDenied: nativeDenial, endingDirectoryCheckVerified: directoryCheck });
  } finally {
    const target = path.resolve(directory);
    assert.equal(path.dirname(target), temp);
    assert.ok(path.basename(target).startsWith("cc-manifest-state-process-"));
    fs.rmSync(target, { recursive: true, force: true });
  }
}
check();
const report = {
  schema: "chainlesschain.rrsi-manifest-state-posix-probes/v1", recordedAt: new Date().toISOString(),
  platform: process.platform, nodeVersion: process.version, uvVersion: process.versions.uv,
  osRelease: os.release(), wsl1,
  nodeBinarySha256: sha(fs.readFileSync(process.execPath)), runnerSha256: sha(fs.readFileSync(fileURLToPath(import.meta.url))),
  sourceCheckpointSha256: sha(fs.readFileSync(checkpointPath)), sourceDigests: checkpoint.sourceDigests,
  scope: "Actual WSL FIFO/dangling symlinks, native late directory rename behavior, and real ending directory mode checks for two backends; native WSL1 EACCES is not ending-check coverage; not full Linux Vitest/macOS/release matrix",
  passedScenarios: results.length, failures: 0, results,
};
fs.writeFileSync(path.join(root, ".work/rrsi-manifest-state-posix.json"), JSON.stringify(report, null, 2) + "\n");
console.log(JSON.stringify({ platform: process.platform, passedScenarios: results.length, results }));
